import re

_SKU_RE = re.compile(r"^([A-Z]{2,4}):(\d{4}):([A-Za-z])$")


def bulk_discount(qty):
    if qty >= 50:
        return 0.12
    if qty >= 10:
        return 0.04
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


def parse_sku(s):
    if not isinstance(s, str):
        raise ValueError(f"invalid SKU: {s!r}")
    m = _SKU_RE.match(s)
    if not m:
        raise ValueError(f"invalid SKU: {s!r}")
    category, number, variant = m.group(1), m.group(2), m.group(3)
    return {"category": category, "number": int(number), "variant": variant}

"""Pricing helpers: bulk discounts, line totals, and SKU parsing (task D1)."""

import re

_SKU_RE = re.compile(r"([A-Z]{2,4}):(\d{4}):([A-Z])")


def bulk_discount(qty):
    """Return the discount rate for an integer quantity.

    0.12 if qty >= 50; 0.04 if qty >= 10; otherwise 0.0.
    """
    if qty >= 50:
        return 0.12
    if qty >= 10:
        return 0.04
    return 0.0


def line_total(unit_price, qty):
    """Return unit_price * qty * (1 - bulk_discount(qty)), rounded to 2 decimals."""
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


def parse_sku(s):
    """Parse a SKU of the form CAT:1234:X.

    CAT is 2-4 upper-case letters, 1234 is a 4-digit number, X is a one-letter
    variant. Returns {"category": str, "number": int, "variant": str}.
    Raises ValueError for anything else.
    """
    if not isinstance(s, str):
        raise ValueError("SKU must be a string: %r" % (s,))
    m = _SKU_RE.fullmatch(s)
    if m is None:
        raise ValueError("invalid SKU: %r" % (s,))
    category, number, variant = m.group(1), m.group(2), m.group(3)
    return {"category": category, "number": int(number), "variant": variant}

